// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/backups", wrapper.ListBackups)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/backups/export", wrapper.ExportBackup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/backups/job", wrapper.GetBackupJob)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/backups/{backupId}/download", wrapper.DownloadBackup)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/backups/{backupId}", wrapper.DeleteBackup)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/backups/{backupId}/restore", wrapper.RestoreBackup)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/backups/upload", wrapper.UploadBackup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/backups/settings", wrapper.GetBackupSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/backups/settings", wrapper.PutBackupSettings)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/backups/run", wrapper.RunBackupNow)
	})

	return r
}
